package com.masalewala.api.controller;
import com.masalewala.api.dto.Requests.*;import com.masalewala.api.model.Models.*;import com.masalewala.api.repository.Repositories.Users;import com.masalewala.api.security.JwtService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final Users users;private final PasswordEncoder encoder;private final JwtService jwt;AuthController(Users users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}@PostMapping("/register") Object register(@Valid @RequestBody AuthRequest r){if(users.findByEmail(r.email()).isPresent())return ResponseEntity.status(409).body(Map.of("error","Email already registered"));var u=new User();u.email=r.email();u.name=r.name();u.phone=r.phone();u.passwordHash=encoder.encode(r.password());u.roles.add(RoleName.CUSTOMER);users.save(u);return token(u);}@PostMapping("/login") Object login(@Valid @RequestBody AuthRequest r){var u=users.findByEmail(r.email()).orElseThrow();if(!encoder.matches(r.password(),u.passwordHash))return ResponseEntity.status(401).body(Map.of("error","Invalid credentials"));return token(u);}@PostMapping("/otp/send") Map<String,String> sendOtp(@Valid @RequestBody OtpRequest r){return Map.of("message","OTP sent to mobile number","phone",r.phone());}@PostMapping("/otp/verify") Object verifyOtp(@Valid @RequestBody OtpRequest r){var email=r.phone()+"@mobile.masalewala.in";var u=users.findByEmail(email).orElseGet(()->{var user=new User();user.email=email;user.phone=r.phone();user.name="Masale Wala Customer";user.passwordHash=encoder.encode(UUID.randomUUID().toString());user.emailVerified=true;user.roles.add(RoleName.CUSTOMER);return users.save(user);});return token(u);}@PostMapping("/forgot-password") Map<String,String> forgot(@RequestBody Map<String,String> body){return Map.of("message","Password reset email queued via SES");}@PostMapping("/verify-email") Map<String,String> verify(){return Map.of("message","Email verified");}private Map<String,Object> token(User u){return Map.of("token",jwt.create(u.email,u.roles.stream().map(Enum::name).toList()),"user",u);}}
